function validate([s, shifts]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 50000) return 's needs 1 to 5 * 10^4 letters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase English letters.';
  if (!Array.isArray(shifts) || shifts.length < 1 || shifts.length > 50000) return 'shifts needs 1 to 5 * 10^4 entries.';
  for (const shift of shifts) {
    if (!Array.isArray(shift) || shift.length !== 3) return 'Each shift is [start, end, direction].';
    const [start, end, direction] = shift;
    if (!Number.isInteger(start) || !Number.isInteger(end) || start < 0 || start > end || end >= s.length) return 'Each shift needs 0 <= start <= end < s.length.';
    if (direction !== 0 && direction !== 1) return 'direction is 0 or 1.';
  }
  return null;
}

