function shiftingLetters(s, shifts) {
  const n = s.length;
  const diff = new Array(n + 1).fill(0);

  for (const [start, end, direction] of shifts) {
    const delta = direction === 1 ? 1 : -1;
    diff[start] += delta;
    diff[end + 1] -= delta;
  }

  const result = [];
  let offset = 0;
  for (let i = 0; i < n; i++) {
    offset += diff[i];
    const code = s.charCodeAt(i) - 97;
    const shifted = (((code + offset) % 26) + 26) % 26;
    result.push(String.fromCharCode(97 + shifted));
  }
  return result.join('');
}

