function shiftingLetters(s, shifts) {
  // Apply every shift letter by letter, exactly as described.
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const letters = s.split('');
  for (const [from, to, dir] of shifts) {
    for (let p = from; p <= to; p++) {
      const at = alphabet.indexOf(letters[p]);
      letters[p] = dir === 1 ? alphabet[at === 25 ? 0 : at + 1] : alphabet[at === 0 ? 25 : at - 1];
    }
  }
  return letters.join('');
}

