function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? pick(1, 8) : pick(3000, 5000);
  const count = size === 'small' ? pick(1, 7) : pick(1500, 2000);
  const letters = rand() < 0.3 ? 'ayz' : 'abcdefghijklmnopqrstuvwxyz';
  let s = '';
  for (let i = 0; i < n; i++) s += letters[pick(0, letters.length - 1)];
  const forwardBias = rand();
  const shifts = [];
  for (let k = 0; k < count; k++) {
    const a = pick(0, n - 1);
    const b = pick(0, n - 1);
    shifts.push([Math.min(a, b), Math.max(a, b), rand() < forwardBias ? 1 : 0]);
  }
  return [s, shifts];
}
